using System;using System.IO;using System.Net;using System.Text;using System.Linq;using System.Collections.Generic;using System.Security.Cryptography;using System.Diagnostics;using System.Web.Script.Serialization;using System.IO.Pipes;using System.Security.Principal;
internal static class UpdateService {
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=32*1024*1024,RecursionLimit=64};
 static Dictionary<string,object> Obj(params object[] p){var o=new Dictionary<string,object>();for(int i=0;i<p.Length;i+=2)o[(string)p[i]]=p[i+1];return o;}
 static string S(Dictionary<string,object> o,string k){object v;return o.TryGetValue(k,out v)&&v is string?(string)v:"";}
 static bool B(Dictionary<string,object> o,string k){object v;return o.TryGetValue(k,out v)&&v is bool&&(bool)v;}
 static long Epoch(Dictionary<string,object> item){object value;return item.TryGetValue("releaseEpoch",out value)?Convert.ToInt64(value):0;}
 static bool Newer(string a,string b){Version x,y;return Version.TryParse(a.TrimStart('v'),out x)&&Version.TryParse(b.TrimStart('v'),out y)&&x>y;}
 static byte[] Fetch(string address,int max){Uri uri;if(!Uri.TryCreate(address,UriKind.Absolute,out uri)||uri.Scheme!="https")throw new Exception("更新地址必须使用 HTTPS");for(int hop=0;hop<=5;hop++){var request=(HttpWebRequest)WebRequest.Create(uri);request.AllowAutoRedirect=false;request.Timeout=20000;request.ReadWriteTimeout=20000;request.UserAgent="Hhub/1.0";using(var response=(HttpWebResponse)request.GetResponse()){int code=(int)response.StatusCode;if(code>=300&&code<400){Uri next;if(hop==5||!Uri.TryCreate(uri,response.Headers["Location"],out next)||next.Scheme!="https")throw new Exception("拒绝不安全或过多的更新重定向");uri=next;continue;}if(response.ContentLength>max)throw new Exception("更新内容过大");using(var stream=response.GetResponseStream())using(var data=new MemoryStream()){byte[] buffer=new byte[32768];int n;while((n=stream.Read(buffer,0,buffer.Length))>0){if(data.Length+n>max)throw new Exception("更新包过大");data.Write(buffer,0,n);}return data.ToArray();}}}throw new Exception("更新重定向失败");}
 static string Digest(byte[] bytes){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
 static Dictionary<string,object> Check(Dictionary<string,object> item,string folder,bool app,Dictionary<string,object> catalogEntry=null,string catalogUrl=""){string feed=S(item,"updateUrl");var result=Obj("id",S(item,"id"),"status","未配置更新源");if(feed.Length==0&&catalogEntry==null)return result;try{var manifest=catalogEntry??(Json.DeserializeObject(Encoding.UTF8.GetString(Fetch(feed,65536))) as Dictionary<string,object>);if(manifest==null||S(manifest,"id")!=S(item,"id"))throw new Exception("更新 ID 不匹配");if(!app&&S(manifest,"author")!=S(item,"author"))throw new Exception("更新作者发生变化");Version parsed;if(!Version.TryParse(S(manifest,"version").TrimStart('v'),out parsed))throw new Exception("更新版本无效");result["version"]=S(manifest,"version");if(!(Epoch(manifest)>Epoch(item)||(Epoch(manifest)==Epoch(item)&&Newer(S(manifest,"version"),S(item,"version"))))){result["status"]="已是最新";return result;}string hash=S(manifest,"sha256").ToLowerInvariant();if(hash.Length!=64||hash.Any(c=>!Uri.IsHexDigit(c)))throw new Exception("缺少有效 SHA-256");string packageUrl=S(manifest,"packageUrl");if(catalogEntry!=null)packageUrl=new Uri(new Uri(catalogUrl),packageUrl).AbsoluteUri;byte[] payload;var packageUri=new Uri(packageUrl);
if(!app&&packageUri.IsFile&&catalogEntry!=null){var sourceUri=new Uri(catalogUrl);string root=Path.GetFullPath(Path.GetDirectoryName(sourceUri.LocalPath))+Path.DirectorySeparatorChar;if(!sourceUri.IsFile||packageUri.IsUnc||!Path.GetFullPath(packageUri.LocalPath).StartsWith(root,StringComparison.OrdinalIgnoreCase)||new FileInfo(packageUri.LocalPath).Length>8*1024*1024)throw new Exception("本地插件包路径或大小无效");payload=File.ReadAllBytes(packageUri.LocalPath);}else payload=Fetch(packageUrl,app?200*1024*1024:8*1024*1024);if(Digest(payload)!=hash)throw new Exception("更新包校验失败");Directory.CreateDirectory(folder);string file=Path.Combine(folder,hash+(app?".exe":".hhub"));File.WriteAllBytes(file+".tmp",payload);if(File.Exists(file))File.Delete(file);File.Move(file+".tmp",file);if(!app){var package=Json.DeserializeObject(Encoding.UTF8.GetString(payload)) as Dictionary<string,object>;if(package==null||S(package,"id")!=S(item,"id")||S(package,"author")!=S(item,"author")||S(package,"version")!=S(manifest,"version"))throw new Exception("插件包身份或版本不匹配");result["manifest"]=package;}result["status"]="更新已下载并验证";result["sha256"]=hash;result["packagePath"]=file;result["ready"]=true;return result;}catch(Exception e){result["status"]="检查失败";result["error"]=e.Message;return result;}}
 static void QuitCore(){try{string sid=WindowsIdentity.GetCurrent().User.Value;using(var pipe=new NamedPipeClientStream(".","HhubPrototype.v1."+sid,PipeDirection.InOut)){pipe.Connect(1000);byte[] data=Encoding.UTF8.GetBytes("{\"op\":\"quit\",\"body\":{}}");pipe.Write(BitConverter.GetBytes(data.Length),0,4);pipe.Write(data,0,data.Length);pipe.Flush();byte[] header=new byte[4];int at=0;while(at<4){int n=pipe.Read(header,at,4-at);if(n<=0)return;at+=n;}int length=BitConverter.ToInt32(header,0);if(length<1||length>33554432)return;data=new byte[length];at=0;while(at<length){int n=pipe.Read(data,at,length-at);if(n<=0)return;at+=n;}pipe.WriteByte(1);pipe.Flush();}}catch{}}
 static void Install(Dictionary<string,object> update,string directory){string file=S(update,"packagePath");if(!File.Exists(file)||Digest(File.ReadAllBytes(file))!=S(update,"sha256"))throw new Exception("安装包校验失败");foreach(var p in Process.GetProcessesByName("Hhub")){try{if(Path.GetDirectoryName(p.MainModule.FileName)==directory)p.CloseMainWindow();}catch{}}System.Threading.Thread.Sleep(500);QuitCore();bool startup=false;using(var key=Microsoft.Win32.Registry.CurrentUser.OpenSubKey("Software\\Microsoft\\Windows\\CurrentVersion\\Run")){string command=key==null?"":key.GetValue("Hhub","") as string;startup=command!=null&&command.IndexOf(Path.Combine(directory,"Hhub.Core.exe"),StringComparison.OrdinalIgnoreCase)>=0;}var info=new ProcessStartInfo(file,"/MERGETASKS=\""+(startup?"startup":"!startup")+"\" /VERYSILENT /SUPPRESSMSGBOXES /NORESTART /CLOSEAPPLICATIONS /DIR=\""+directory+"\""){UseShellExecute=false,CreateNoWindow=true};Process.Start(info);}
 public static int Main(string[] args){if(args.Length<3)return 2;ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;try{var input=Json.DeserializeObject(File.ReadAllText(args[1])) as Dictionary<string,object>;if(args[0]=="--apply"){Install(input,S(input,"installDirectory"));return 0;}string folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"HhubPrototype","updates");var plugins=new List<object>();object values;var installed=input.TryGetValue("plugins",out values)?(object[])values:new object[0];
var catalog=new List<Dictionary<string,object>>();string catalogError="";
if(installed.Length>0&&input.TryGetValue("pluginCatalog",out values)) {
 var settings=values as Dictionary<string,object>;object configured;
 var sources=settings!=null&&settings.TryGetValue("sources",out configured)?(object[])configured:settings==null?new object[0]:new object[]{settings};
 foreach(Dictionary<string,object> source in sources) {
  object enabled;if(source.TryGetValue("enabled",out enabled)&&enabled is bool&&!(bool)enabled)continue;
  try {
   string address=S(source,"indexUrl");Uri uri=new Uri(address);byte[] bytes=uri.IsFile?File.ReadAllBytes(uri.LocalPath):Fetch(address,262144);
   if(bytes.Length>262144)throw new Exception("插件库清单过大");
   var index=Json.DeserializeObject(Encoding.UTF8.GetString(bytes).TrimStart('\ufeff')) as Dictionary<string,object>;
   if(index==null||!index.ContainsKey("schemaVersion")||Convert.ToInt32(index["schemaVersion"])!=1||!index.ContainsKey("plugins"))throw new Exception("插件库索引格式不支持");
   foreach(var value in (object[])index["plugins"]) {var entry=value as Dictionary<string,object>;if(entry==null)continue;entry["sourceIndexUrl"]=address;catalog.Add(entry);}
  }catch(Exception error){catalogError=error.Message;}
 }
}
foreach(Dictionary<string,object> plugin in installed) {
 var entries=catalog.Where(e=>S(e,"id")==S(plugin,"id")&&S(e,"author")==S(plugin,"author")).GroupBy(e=>S(e,"version")+"\n"+S(e,"sha256")).Select(g=>g.First()).ToArray();
 // Ambiguous identities across libraries require an explicit choice in the market.
 if(entries.Length==1)plugins.Add(Check(plugin,folder,false,entries[0],S(entries[0],"sourceIndexUrl")));
 else if(entries.Length>1)plugins.Add(Obj("id",S(plugin,"id"),"status","多个插件库包含此插件，请在插件市场选择更新来源"));
 else if(S(plugin,"updateUrl").Length>0)plugins.Add(Check(plugin,folder,false));
 else if(catalogError.Length>0)plugins.Add(Obj("id",S(plugin,"id"),"status","部分插件库连接失败","error",catalogError));
 else plugins.Add(Check(plugin,folder,false));
}
var application=Check((Dictionary<string,object>)input["application"],folder,true);var output=Obj("completed",true,"application",application,"plugins",plugins.ToArray(),"checkedAt",DateTimeOffset.UtcNow.ToUnixTimeSeconds());File.WriteAllText(args[2]+".tmp",Json.Serialize(output),new UTF8Encoding(false));if(File.Exists(args[2]))File.Delete(args[2]);File.Move(args[2]+".tmp",args[2]);if(B(input,"autoInstallApplication")&&B(application,"ready"))Install(application,S(input,"installDirectory"));return 0;}catch(Exception e){File.WriteAllText(args[2],Json.Serialize(Obj("completed",true,"error",e.Message)),new UTF8Encoding(false));return 1;}}
}
